// === Zentrale Konfiguration – hier pflegen ===
const CONFIG = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  // Zeitraum in UTC. 01.08.2026 00:00 MESZ = 31.07.2026 22:00 UTC
  createdAtMin: '2026-07-31T22:00:00Z',
  // null = "bis jetzt". Fixes Ende z.B.: '2026-08-03T21:59:59Z'
  createdAtMax: null,

  // Zu entfernende Position: Zauberbüchse Buch
  altSku: '001-01',

  // Zusatzbedingung: Bestellung muss diese Position ebenfalls aktiv enthalten.
  // Sie wird NICHT angetastet.
  bedingungSku: 'ZB-2026-08-02',

  // Ersatzposition: Zauberbüchse August Buch
  // Preis wird NICHT gesetzt – Shopify zieht ihn aus der Variante.
  neuSku: 'ZB-2026-08-01',

  // Optionaler Länderfilter, z.B. ['DE'] oder ['DE','AT'].
  // null = alle Länder verarbeiten.
  nurLaender: null,

  // Einzelne Bestellungen ausschließen (orderId)
  ausnahmen: [],

  notifyCustomer: false,
  staffNote: 'Automatischer Positionstausch: Zauberbüchse Buch (001-01) entfernt, Zauberbüchse August Buch (ZB-2026-08-01) ergänzt.'
};

const staticData = $getWorkflowStaticData('global');
staticData.config = CONFIG;
staticData.toFix = [];
staticData.skipped = [];
staticData.variantMap = {};

return [{ json: { config: CONFIG } }];

const resp = $input.first().json;
const config = $('Config').first().json.config;
const edges = resp?.data?.productVariants?.edges || [];

const map = {};
for (const e of edges) {
  const sku = String(e.node.sku || '').trim();
  if (sku) map[sku] = { gid: e.node.id, preis: e.node.price, titel: e.node.displayName };
}

if (!map[config.neuSku]) {
  throw new Error('Variante in Shopify nicht gefunden für SKU: ' + config.neuSku);
}

const staticData = $getWorkflowStaticData('global');
staticData.variantMap = map;

return [{ json: { variantMap: map } }];

const config = $('Config').first().json.config;
const shop = config.shop;

let initUrl = `https://${shop}.myshopify.com/admin/api/${config.apiVersion}/orders.json`
  + `?limit=250`
  + `&status=any`
  + `&order=${encodeURIComponent('created_at asc')}`
  + `&created_at_min=${encodeURIComponent(config.createdAtMin)}`
  + `&fields=id,name,created_at,currency,presentment_currency,tags,line_items,shipping_address`;

if (config.createdAtMax) {
  initUrl += `&created_at_max=${encodeURIComponent(config.createdAtMax)}`;
}

const staticData = $getWorkflowStaticData('global');
staticData.toFix = [];
staticData.skipped = [];

return [{
  json: {
    nextUrl: initUrl,
    hasNext: true,
    accessToken: $('Token holen').first().json.access_token
  }
}];

const response = $input.first().json;
const orders = response.body?.orders || response.orders || [];
const headers = response.headers || {};

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.toFix)) staticData.toFix = [];
if (!Array.isArray(staticData.skipped)) staticData.skipped = [];

const ALT_SKU = String(config.altSku).trim();
const BEDINGUNG_SKU = String(config.bedingungSku).trim();

for (const order of orders) {
  const lineItems = order.line_items || [];

  // current_quantity: bereits entfernte Positionen behalten quantity 1
  const aktive = lineItems.filter(li => Number(li.current_quantity) > 0);

  const buchPositionen = aktive.filter(li => String(li.sku || '').trim() === ALT_SKU);
  const hatBedingung = aktive.some(li => String(li.sku || '').trim() === BEDINGUNG_SKU);

  // Nur Bestellungen mit ALT_SKU *und* BEDINGUNG_SKU
  if (!buchPositionen.length || !hatBedingung) continue;

  const datensatz = {
    orderId: order.id,
    orderName: order.name,
    createdAt: order.created_at,
    currency: order.presentment_currency || order.currency,
    land: order.shipping_address?.country_code || null,
    positionen: buchPositionen.map(li => ({
      lineItemId: li.id,
      title: li.title,
      variantId: li.variant_id,
      sku: li.sku,
      aktuellerPreis: li.price,
      quantity: li.quantity,
      currentQuantity: li.current_quantity
    }))
  };

  if (Array.isArray(config.ausnahmen) && config.ausnahmen.includes(order.id)) {
    staticData.skipped.push({ ...datensatz, grund: 'Bestellung steht in Config.ausnahmen' });
    continue;
  }

  if (Array.isArray(config.nurLaender) && !config.nurLaender.includes(datensatz.land)) {
    staticData.skipped.push({ ...datensatz, grund: 'Land ' + datensatz.land + ' nicht in Config.nurLaender' });
    continue;
  }

  staticData.toFix.push(datensatz);
}

// Cursor-Pagination über Link-Header (rel="next").
// Filterparameter gehören NUR in die erste URL, danach nur page_info + limit.
const linkHeader = String(headers.link || headers.Link || '');
let nextUrl = null;
const nextPart = linkHeader.split(',').find(p => p.includes('rel="next"'));
if (nextPart) {
  const m = nextPart.match(/<([^>]+)>/);
  if (m) nextUrl = m[1];
}

return [{
  json: {
    nextUrl: nextUrl,
    hasNext: !!nextUrl,
    collectedCount: staticData.toFix.length,
    skippedCount: staticData.skipped.length
  }
}];

const tokenItem = $input.first().json;
const urlItem = $input.last().json;

return [{
  json: {
    accessToken: tokenItem.access_token,
    nextUrl: urlItem.nextUrl,
    hasNext: urlItem.hasNext
  }
}];

const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];

return collected.map(row => ({ json: row }));

// Ein Item je zu tauschende Buch-Position
const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const collected = staticData.toFix || [];
const map = staticData.variantMap || {};

const skuNeu = config.neuSku;

const out = [];
for (const order of collected) {
  for (const pos of order.positionen) {
    out.push({
      json: {
        orderId: order.orderId,
        orderName: order.orderName,
        orderGid: `gid://shopify/Order/${order.orderId}`,
        createdAt: order.createdAt,
        currency: order.currency,
        land: order.land,
        altSku: pos.sku,
        altPreis: pos.aktuellerPreis,
        altLineItemId: pos.lineItemId,
        oldLineItemGid: `gid://shopify/CalculatedLineItem/${pos.lineItemId}`,
        menge: Number(pos.currentQuantity) || 1,
        neuSku: skuNeu,
        neuVariantGid: map[skuNeu]?.gid
      }
    });
  }
}

return out;

// TESTGATE: verarbeitet nur die erste gefundene Position.
// Für den Vollauf diesen Node deaktivieren oder löschen.
return $input.all().slice(0, 1);

const staticData = $getWorkflowStaticData('global');
const skipped = staticData.skipped || [];

if (!skipped.length) {
  return [{ json: { hinweis: 'Keine Bestellung übersprungen.' } }];
}

return skipped.map(s => ({
  json: { ...s, hinweis: 'Nicht automatisch korrigiert – manuell prüfen.' }
}));

const item = $('Loop Over Items').item.json;

const body = {
  query: `mutation orderEditBegin($id: ID!) {
    orderEditBegin(id: $id) {
      calculatedOrder {
        id
        lineItems(first: 100) { edges { node { id sku title quantity } } }
      }
      userErrors { field message }
    }
  }`,
  variables: { id: item.orderGid }
};

return [{
  json: {
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
}];

const resp = $input.first().json;
const begin = resp?.data?.orderEditBegin;
const errs = begin?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditBegin userErrors: ' + JSON.stringify(errs));
}
const calcOrderId = begin?.calculatedOrder?.id;
if (!calcOrderId) {
  throw new Error('Keine calculatedOrder.id erhalten: ' + JSON.stringify(resp));
}

const src = $('Loop Over Items').item.json;

// CalculatedLineItem-GID der Buch-Position direkt aus dem CalculatedOrder holen,
// Fallback: aus der REST-lineItemId konstruiert.
const edges = begin?.calculatedOrder?.lineItems?.edges || [];
const treffer = edges.find(e =>
  String(e.node.sku || '').trim() === String(src.altSku).trim() &&
  Number(e.node.quantity) > 0
);
const oldLineItemGid = treffer ? treffer.node.id : src.oldLineItemGid;

return [{
  json: {
    calcOrderId,
    oldLineItemGid,
    orderName: src.orderName,
    orderGid: src.orderGid,
    currency: src.currency,
    land: src.land,
    menge: src.menge,
    altSku: src.altSku,
    altPreis: src.altPreis,
    neuSku: src.neuSku,
    neuVariantGid: src.neuVariantGid
  }
}];

const item = $input.item.json;

const body = {
  query: `mutation orderEditAddVariant($id: ID!, $variantId: ID!, $quantity: Int!, $allowDuplicates: Boolean) {
    orderEditAddVariant(id: $id, variantId: $variantId, quantity: $quantity, allowDuplicates: $allowDuplicates) {
      calculatedLineItem {
        id
        title
        sku
        quantity
        discountedUnitPriceSet {
          shopMoney { amount currencyCode }
          presentmentMoney { amount currencyCode }
        }
      }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    variantId: item.neuVariantGid,
    quantity: item.menge,
    allowDuplicates: true
  }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const add = resp?.data?.orderEditAddVariant;
const errs = add?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditAddVariant userErrors: ' + JSON.stringify(errs));
}

const li = add?.calculatedLineItem || null;

return {
  json: {
    ...$('CalcOrder auslesen').item.json,
    neuLineItem: li,
    neuPreis: li?.discountedUnitPriceSet?.presentmentMoney || null
  }
};

const item = $input.item.json;

const body = {
  query: `mutation orderEditSetQuantity($id: ID!, $lineItemId: ID!, $quantity: Int!, $restock: Boolean) {
    orderEditSetQuantity(id: $id, lineItemId: $lineItemId, quantity: $quantity, restock: $restock) {
      calculatedLineItem { id quantity }
      userErrors { field message }
    }
  }`,
  variables: {
    id: item.calcOrderId,
    lineItemId: item.oldLineItemGid,
    quantity: 0,
    restock: false
  }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const setQty = resp?.data?.orderEditSetQuantity;
const errs = setQty?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditSetQuantity userErrors: ' + JSON.stringify(errs));
}

return {
  json: {
    ...$('Add-Ergebnis prüfen').item.json,
    altPositionEntfernt: true,
    removedLineItem: setQty?.calculatedLineItem || null
  }
};

const resp = $input.first().json;
const commit = resp?.data?.orderEditCommit;
const errs = commit?.userErrors || [];
if (errs.length) {
  throw new Error('orderEditCommit userErrors: ' + JSON.stringify(errs));
}

const src = $('Remove-Ergebnis prüfen').first().json;

return [{
  json: {
    status: 'OK',
    orderName: src.orderName,
    land: src.land,
    currency: src.currency,
    altSku: src.altSku,
    altPreis: src.altPreis,
    neuSku: src.neuSku,
    neuPreis: src.neuPreis,
    committedOrder: commit?.order || null
  }
}];

const item = $input.item.json;

// maximumRefundableV2 auf order.transactions liefert immer 0 – der Wert wird
// nur im Kontext von SuggestedRefund befüllt. Deshalb suggestedRefund abfragen.
const body = {
  query: `query($id: ID!) {
    order(id: $id) {
      id
      name
      totalOutstandingSet { presentmentMoney { amount currencyCode } }
      suggestedRefund {
        maximumRefundableSet { presentmentMoney { amount currencyCode } }
        suggestedTransactions {
          gateway
          kind
          amountSet { presentmentMoney { amount currencyCode } }
          maximumRefundableSet { presentmentMoney { amount currencyCode } }
          parentTransaction { id kind status }
        }
      }
      transactions(first: 20) {
        id
        kind
        status
        gateway
        amountSet { presentmentMoney { amount currencyCode } }
      }
    }
  }`,
  variables: { id: item.committedOrder?.id || item.orderGid }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const order = resp?.data?.order;
if (!order) {
  throw new Error('Order-Query ohne Ergebnis: ' + JSON.stringify(resp));
}

const src = $('Commit-Ergebnis prüfen').first().json;

// totalOutstandingSet: positiv = Kunde schuldet uns, negativ = wir schulden dem Kunden
const outstanding = Number(order.totalOutstandingSet?.presentmentMoney?.amount || 0);
const currency = order.totalOutstandingSet?.presentmentMoney?.currencyCode || src.currency;

// Obergrenze + Parent aus suggestedRefund. maximumRefundableV2 auf
// order.transactions liefert immer 0 und ist als Deckel unbrauchbar.
const sr = order.suggestedRefund || null;
const sugg = (sr?.suggestedTransactions || [])[0] || null;

let maxRefund = Number(
  sugg?.maximumRefundableSet?.presentmentMoney?.amount
  ?? sr?.maximumRefundableSet?.presentmentMoney?.amount
  ?? 0
);
let parentId = sugg?.parentTransaction?.id || null;
let gateway = sugg?.gateway || null;

// Fallback über die Transaktionsliste, falls suggestedRefund leer bleibt
if (!parentId || !maxRefund) {
  const parent = (order.transactions || []).find(t =>
    ['SALE', 'CAPTURE'].includes(t.kind) && t.status === 'SUCCESS'
  );
  parentId = parentId || parent?.id || null;
  gateway = gateway || parent?.gateway || null;
  if (!maxRefund) {
    maxRefund = Number(parent?.amountSet?.presentmentMoney?.amount || 0);
  }
}

let refundNoetig = false;
let betrag = 0;
let grund = null;
let gedeckelt = false;

if (outstanding >= 0) {
  grund = 'Kein Guthaben zugunsten des Kunden (outstanding ' + outstanding + ')';
} else if (!parentId || !gateway) {
  grund = 'Keine erstattbare Zahlungstransaktion gefunden – manuell erstatten';
} else {
  const gewuenscht = Math.abs(outstanding);
  betrag = Math.round(Math.min(gewuenscht, maxRefund) * 100) / 100;
  gedeckelt = betrag < gewuenscht;

  if (betrag <= 0) {
    grund = 'Erstattbarer Betrag ist 0 (maxRefund ' + maxRefund + ') – manuell erstatten';
  } else {
    refundNoetig = true;
    if (gedeckelt) {
      grund = 'Teilerstattung: ' + betrag + ' von ' + gewuenscht + ' (Limit ' + maxRefund + ')';
    }
  }
}

return {
  json: {
    ...src,
    commitStatus: src.status,
    orderGid: order.id,
    orderName: order.name,
    outstanding,
    currency,
    maxRefund,
    refundNoetig,
    refundBetrag: betrag.toFixed(2),
    gedeckelt,
    parentTransactionId: parentId,
    gateway,
    grund,
    accessToken: $('Token holen 2').first().json.access_token
  }
};

const item = $input.item.json;

// WICHTIG: keine refundLineItems. Die Position wurde per Order Edit auf 0
// gesetzt, ein RefundLineItem darauf wird von Shopify abgelehnt.
// Refund.transactions ist eine Connection -> edges { node { ... } }.
const body = {
  query: `mutation refundCreate($input: RefundInput!) {
    refundCreate(input: $input) {
      refund {
        id
        createdAt
        totalRefundedSet { presentmentMoney { amount currencyCode } }
        transactions(first: 5) {
          edges {
            node { id kind status gateway errorCode }
          }
        }
      }
      userErrors { field message }
    }
  }`,
  variables: {
    input: {
      orderId: item.orderGid,
      currency: item.currency,
      notify: false,
      note: 'Automatische Rückerstattung nach Positionstausch August 2026',
      transactions: [{
        orderId: item.orderGid,
        parentId: item.parentTransactionId,
        gateway: item.gateway,
        kind: 'REFUND',
        amount: item.refundBetrag
      }]
    }
  }
};

return {
  json: {
    ...item,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const src = $('Query bauen (refundCreate)').first().json;

// GraphQL-Fehler auf oberster Ebene (ungültige Query, fehlender Scope, ...).
// Shopify antwortet dabei mit HTTP 200, der HTTP-Node schlägt also nicht fehl.
const gqlErrors = resp?.errors || [];

const payload = resp?.data?.refundCreate;
const errs = payload?.userErrors || [];
const refund = payload?.refund || null;

// Refund.transactions ist eine Connection
const txs = (refund?.transactions?.edges || []).map(e => e.node);

// Ein Refund-Objekt allein heißt nicht, dass Geld geflossen ist ->
// Status der Refund-Transaktionen auswerten.
const problem = txs.filter(t => ['FAILURE', 'ERROR'].includes(t.status));

let status = 'OK';
if (gqlErrors.length) status = 'GRAPHQL_FEHLER';
else if (errs.length) status = 'USER_ERROR';
else if (!refund) status = 'KEIN_REFUND';
else if (problem.length) status = 'GATEWAY_FEHLER';
else if (txs.some(t => t.status === 'PENDING')) status = 'PENDING';

// Bewusst kein throw: ein abgelehnter Refund soll den Loop nicht stoppen.
return {
  json: {
    status,
    orderName: src.orderName,
    land: src.land,
    currency: src.currency,
    refundBetrag: src.refundBetrag,
    gedeckelt: src.gedeckelt,
    gateway: src.gateway,
    refundId: refund?.id || null,
    tatsaechlichErstattet: refund?.totalRefundedSet?.presentmentMoney?.amount || null,
    transaktionen: txs,
    userErrors: errs,
    gqlErrors: gqlErrors.map(e => e.message),
    manuellPruefen: status !== 'OK'
  }
};
